 "content": "def transform(grid):
    """Fill each completely enclosed rectangular frame according to its cavity size.

    Odd-by-odd cavities are filled with 7; even-by-even cavities with 2.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            # Gather this color's 4-connected object.
            comp = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); comp.add((yy,xx)); stack.append((yy,xx))
            y0, y1 = min(y for y,x in comp), max(y for y,x in comp)
            x0, x1 = min(x for y,x in comp), max(x for y,x in comp)
            if y1 <= y0+1 or x1 <= x0+1:
                continue
            # Only fill a closed rectangular perimeter; scattered shapes aren't frames.
            perimeter = {(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1)
                         if y in (y0,y1) or x in (x0,x1)}
            if not perimeter <= comp:
                continue
            inner_h, inner_w = y1-y0-1, x1-x0-1
            fill = 7 if inner_h % 2 == 1 and inner_w % 2 == 1 else 2
            for y in range(y0+1,y1):
                for x in range(x0+1,x1):
                    out[y][x] = fill
    return out
